BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='60s';
LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE swsi_before ON COMMIT DROP AS SELECT id, to_jsonb(q) AS row FROM public.questions q;
CREATE TEMP TABLE swsi_batch(id text primary key, status text, note text, url text) ON COMMIT DROP;
INSERT INTO swsi_batch VALUES ('SP-115-2-031','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2026-07-25。本題考社會福利基本法第3條：社會福利應本於社會包容、城鄉均衡及永續發展之原則，並兼顧家庭及社會責任，以預防、減緩社會問題，促進國民福祉為目標。本法 2023-05-24 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050213'),('SP104-1-09','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考失業陷阱概念及就業保險法之提早就業獎助津貼。就業保險法第10條規定本保險給付包括提早就業獎助津貼，第11條第1項第2款規定符合失業給付請領條件、於失業給付請領期間屆滿前受僱工作並參加本保險三個月以上者得請領，第18條規定按其尚未請領之失業給付金額之百分之五十一次發給，可鼓勵失業者提早就業，選項(D)仍正確；選項(B)稱保險型給付較救助型給付更容易有失業陷阱，屬概念錯誤。最後修正公布日：第10條 2009-04-22、第11條 2009-04-22、第18條 2002-05-15（制定公布），本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050021'),('SP104-1-39','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考老年農民福利津貼暫行條例。第3條規定老年農民須年滿六十五歲、在國內設有戶籍且最近三年內每年居住超過一百八十三日（選項A正確），申領時參加農民健康保險且加保年資合計十五年以上（選項B正確）；第4條規定自 2012-01-01 起福利津貼調整為每月新臺幣七千元，發放至本人死亡當月止（選項C正確），其後每四年調整一次，並非每三年（選項D錯誤）。第3條最後修正公布日 2014-07-16；第4條於 2018-06-13 修正，僅修正排富條件之所得認定及財產扣除項目等規定，七千元及每四年調整一次之規定未變，就本題規定考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=M0090015'),('SP104-1-40','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2015-02-07。本題考社會保險之給付形式。全民健康保險法第40條規定保險對象發生疾病、傷害事故或生育時，由保險醫事服務機構提供保險醫療服務，屬服務給付（選項C）；勞工保險條例第53條失能給付、國民年金法第32條之1生育給付、就業保險法第19條之2育嬰留職停薪津貼均為現金給付。國民年金法第32條之1 於 2015-12-16 修正為一次發給二個月、就業保險法第19條之2 於 2015-02-04 及 2022-01-12 修正，均仍為現金給付；全民健康保險法第40條（2011-01-26 全文修正）及勞工保險條例第53條（2008-08-13）於考試日之後未再修正，就本題規定考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0060001'),('SP105-1-02','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-01-30。本題考就業保險法失業給付及育嬰留職停薪津貼。第11條第1項第1款規定失業給付須非自願離職、退保當日前三年內保險年資合計滿一年以上（選項A、C正確）；第16條規定失業給付最長發給六個月，離職退保時已年滿四十五歲或領有身心障礙證明者最長發給九個月，並無青年失業者發給九個月之規定（選項B錯誤）；第19條之2規定育嬰留職停薪津貼於同時撫育子女二人以上之情形以發給一人為限（選項D正確）。最後修正公布日：第11條 2009-04-22、第16條 2009-04-22；第19條之2 於 2015-02-04 及 2022-01-12 修正，均保留同時撫育子女二人以上以發給一人為限之規定，就本題規定考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050021'),('SP105-2-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2016-07-23。本題考原住民族工作權保障法第3、4、5條。第3條規定中央主管機關為原住民族委員會（選項A之行政院原住民委員會為舊稱，錯誤）；第4條規定各級政府機關、公立學校及公營事業機構，除位於澎湖、金門、連江縣外，其僱用約僱人員、駐衛警察、技工、駕駛、工友、清潔工、收費管理員等人員之總額，每滿一百人應有原住民一人（選項C正確；選項B「僱用所有人員之總額」錯誤）；第5條規定原住民地區之機關僱用上開人員之總額應有三分之一以上為原住民（選項D「僱用所有人員之總額」錯誤）。最後修正公布日：第3條 2015-02-04、第4條 2001-10-31（制定公布）、第5條 2001-10-31（制定公布），本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0130006'),('SP106-2-08','changed',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-07-29。本題考就業保險法。考試時條文（2015-02-04 修正後）：第16條規定領有社政主管機關核發之身心障礙證明者失業給付最長發給九個月（選項A正確）；第19條之2規定父母同為被保險人者，應分別請領育嬰留職停薪津貼，不得同時為之（選項B正確）；第11條第1項第1款規定失業給付之請領條件（選項C正確）；第13條規定申請人僅於推介工作之工資低於其每月得請領之失業給付數額，或工作地點距離日常居住處所三十公里以上而不接受時，仍得請領失業給付，並無得以專長不符為由拒絕之規定（選項D錯誤）。現行條文：第19條之2 經 2022-01-12 修正（2022-01-18 施行），已刪除父母同為被保險人者應分別請領、不得同時為之之限制，選項(B)已不符現行條文；第11、13、16條未再修正。本題官方答案依考試時條文判定；作答時請以現行條文為準。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050021'),('SP107-1-15','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考就業保險法失業認定。第11條第1項第1款規定失業給付須於非自願離職辦理退保當日前三年內保險年資合計滿一年以上，並自求職登記之日起十四日內仍無法推介就業或安排職業訓練，選項(A)「滿6個月以上」不符資格；第25條規定申請人應檢附離職證明文件（選項B）；第13條規定推介工作之工資低於其每月得請領之失業給付數額而不接受者，仍得請領失業給付（選項C）。最後修正公布日：第11條 2009-04-22、第13條 2009-04-22、第25條 2009-04-22，本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050021'),('SP107-1-38','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2018-02-03。本題考全民健康保險法第25條：本保險財務，由保險人至少每五年精算一次，每次精算二十五年。最後修正公布日：第25條 2011-01-26（全文修正），其後 2020、2021、2023 年之修正均未涉及第25條，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=L0060001'),('SP108-2-20','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2019-07-27。本題考公益彩券發行條例第6條：發行機構應將公益彩券發行之盈餘專供政府補助國民年金、全民健康保險準備及社會福利支出之用，不包括補助中小學教育（選項B）。最後修正公布日：第6條 2008-05-28，其後本條例僅於 2016-11-09 修正第4條，本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0380187'),('SP113-2-10','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-07-27。本題考社會投資福利國家之概念。社會救助法第2條規定社會救助分生活扶助、醫療補助、急難救助及災害救助，第10、11條規定低收入戶得申請生活扶助、以現金給付為原則，屬事後之所得維持給付，最不屬於社會投資之政策領域（選項C）。最後修正公布日：第2條 1997-11-19（全文修正）、第10條 2005-01-19、第11條 2015-12-30，本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP113-2-13','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2024-07-27。本題考社會福利基本法第13條：各級政府應以現金給付、實物給付、租稅優惠、機會提供或其他方式，保障國民基本生活。本法 2023-05-24 制定公布施行，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050213'),('SP114-1-11','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2025-02-08。本題考福利之財務與提供部門。社會救助法第21條規定急難救助由民眾向戶籍所在地主管機關申請，由政府辦理（選項B）；地方政府愛心專戶以民間捐款為財源、由政府提供服務或給付（選項D），非法規條文。最後修正公布日：第21條 2010-12-29，本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050078'),('SP114-2-09','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2025-07-26。本題考勞動再商品化概念。就業保險法第10、11條規定之提早就業獎助津貼，依第18條按尚未請領之失業給付金額之百分之五十一次發給，係鼓勵失業者提早重返勞動市場，最貼近再商品化（選項D）；勞工保險條例第63條之遺屬年金給付及其餘選項之職業災害補償、失能給付，屬所得保障給付。最後修正公布日：就業保險法第10條 2009-04-22、第11條 2009-04-22、第18條 2002-05-15（制定公布）；勞工保險條例第63條 2008-08-13，本題考試日之後均未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=N0050021'),('SP114-2-18','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2025-07-26。本題考公益彩券發行條例第5、6條：盈餘指售出彩券券面總金額扣除應發獎金總額及發行彩券銷管費用等後之餘額（選項A正確）；獎金支出不得超過發行彩券券面總金額之百分之七十五（選項B正確）；發行彩券銷管費用不得超過售出彩券券面總金額百分之十五（選項C正確）；盈餘不得充抵依財政收支劃分法已分配及補助之社會福利經費（選項D錯誤）。最後修正公布日：第5條 1995-07-05（制定公布）、第6條 2008-05-28，本題考試日之後未再修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=G0380187'),('SW-106-1-30','verified_current',$swsi$考試時點法規核對（逐條人工核對）：本題考試日 2017-02-18。本題考協助積極自立脫離貧窮實施辦法第4條：脫離貧窮措施之方式為教育投資、就業自立、資產累積、社區產業、社會參與及其他創新、多元或實驗性服務，不包括失業給付（選項C）。本辦法 2016-06-06 訂定發布，其後未曾修正，考試時條文與現行條文相同。官方答案依現行條文仍正確。依據：法務部全國法規資料庫現行條文、法規沿革及歷史條文（2026-11-25 查核）。$swsi$,'https://law.moj.gov.tw/LawClass/LawAll.aspx?pcode=D0050199');
DO $g$ BEGIN
IF (SELECT count(*) FROM swsi_before)<>4800 THEN RAISE EXCEPTION 'count'; END IF;
IF (SELECT count(*) FROM swsi_batch)<>16 THEN RAISE EXCEPTION 'batch size'; END IF;
IF (SELECT count(*) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_status='unreviewed' AND q.legal_checked_at IS NULL AND q.legal_note IS NULL AND q.legal_source_url IS NULL)<>16 THEN RAISE EXCEPTION 'preimage mismatch'; END IF;
END $g$;
UPDATE public.questions q SET legal_status=b.status, legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz, legal_note=b.note, legal_source_url=b.url
FROM swsi_batch b WHERE q.id=b.id;
DO $a$ BEGIN
IF (SELECT md5(string_agg(concat_ws(chr(31),q.id,q.legal_status,q.legal_note,q.legal_source_url),chr(30) ORDER BY q.id)) FROM public.questions q JOIN swsi_batch b USING(id) WHERE q.legal_checked_at='2026-11-25T12:00:00+00:00'::timestamptz)<>'77acff49497487f4313aa9e3c33ae947' THEN RAISE EXCEPTION 'postimage mismatch'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b FULL JOIN public.questions q USING(id) WHERE coalesce(b.id,q.id) NOT IN (SELECT id FROM swsi_batch) AND b.row IS DISTINCT FROM to_jsonb(q)) THEN RAISE EXCEPTION 'unrelated change'; END IF;
IF EXISTS (SELECT 1 FROM swsi_before b JOIN public.questions q USING(id) WHERE b.id IN (SELECT id FROM swsi_batch) AND (b.row - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url') IS DISTINCT FROM (to_jsonb(q) - 'legal_status' - 'legal_checked_at' - 'legal_note' - 'legal_source_url')) THEN RAISE EXCEPTION 'non-legal field changed'; END IF;
END $a$;
SELECT count(*) FILTER (WHERE q.legal_status='verified_current') verified_15, count(*) FILTER (WHERE q.legal_status='changed') changed_1, count(*) total_16 FROM public.questions q JOIN swsi_batch b USING(id);
COMMIT;
